  raise ValidationError(str(obj))

for date_str, price_data in obj[key].items():
    date = dateutil.parser.parse(date_str)
    time = datetime.datetime.combine(date, datetime.datetime.min.time()).replace(hour=20)
    if time in existing:
      continue
    vals_list.append({
        'price': float(price_data['4. close']),
        'time': time,
    })

asset.write({'price_ids': [(0, 0, values) for values in vals_list]})

