modes = ['realtime', 'intraday', 'daily']
from_currency = self.company_id.currency_id.name
currencies = {c.name: c for c in self.env['res.currency'].search([('name', '!=', from_currency)])}

alert = ''
for to_currency, currency_id in currencies.items():
  for mode in modes:
    try:
      self.produce(variables={
        'mode': mode,
        'from_currency': from_currency,
        'to_currency': to_currency,
        'currency_id': currency_id,
      })
    except ValidationError as error:
      _logger.exception(error)
      alert = error.args[0]
    else:
      break
  else:
    raise ValidationError("Unable to fetch currencies: %s" % alert)

def call_api(params, key):
  params.update({
    'from_currency': from_currency,
    'to_currency': to_currency,
    'from_symbol': from_currency,
    'to_symbol': to_currency,
    'apikey': self.authorization,
  })
  resp = requests.get(
    url=self.location,
    params=params,
  )
  json_data = resp.json()
  if key not in json_data:
      raise ValidationError(str(json_data))
  return json_data[key]

if mode == 'realtime':
  vals = call_api({'function': 'CURRENCY_EXCHANGE_RATE'}, 'Realtime Currency Exchange Rate')
  obj = {dateutil.parser.parse(vals['6. Last Refreshed']).date(): float(vals['5. Exchange Rate'])}
elif mode == 'intraday':
  vals = call_api({'function': 'FX_INTRADAY', 'interval': '5min'}, 'Time Series FX (5min)')
  obj = {}
  for d_str, w in vals.items():
      date = dateutil.parser.parse(d_str).date()
      if date not in obj:
          obj[date] = float(w['4. close'])
elif mode == 'daily':
    vals = call_api({'function': 'FX_DAILY'}, 'Time Series FX (Daily)')
    obj = {dateutil.parser.parse(d_str).date(): float(w['4. close']) for d_str, w in vals.items() }
elif mode == 'weekly':
    vals = call_api({'function': 'FX_WEEKLY'}, 'Time Series FX (Weekly)')
    obj = {dateutil.parser.parse(d_str).date(): float(w['4. close']) for d_str, w in vals.items() }

obj = {k.strftime('%Y-%m-%d'):v for k, v in obj.items()}

# _logger.info(f"Update {mode} rates on {to_currency}")
Rate = self.env['res.currency.rate']
for date, rate in obj.items():
    rate_record = Rate.search([
        ('currency_id', '=', currency_id.id),
        ('name', '=', date),
    ])
    if rate_record:
        rate_record.write({'rate': rate})
    else:
        Rate.create({
            'name': date,
            'currency_id': currency_id.id,
            'rate': rate,
        })
self.env['investment.position'].search([('asset_id.currency_id', '=', currency_id.id)])._compute_position_aggregate()

